// Pins the security properties of SlcmCredentials.
//
// These are not style checks. The password reaches exactly one place - the
// create-session body - and the assertions below are what stop a future edit
// from widening that without anyone noticing: a `toJson` added for convenience,
// or a `toString` regenerated by an IDE template, would both fail here.

import 'package:flutter_test/flutter_test.dart';
import 'package:ulaskelas/features/kalkulator/domain/entities/slcm_credentials.dart';

const _password = 'sup3r-s3cret-pw';

void main() {
  group('request body', () {
    test('carries the credentials the backend contract asks for', () {
      final body = SlcmCredentials(
        username: 'muhammad.rafi419',
        password: _password,
        givenSemester: '5',
      ).toRequestBody();

      expect(body, <String, dynamic>{
        'username': 'muhammad.rafi419',
        'password': _password,
        'given_semester': '5',
      });
    });

    test('omits given_semester entirely when none was supplied', () {
      final body = SlcmCredentials(
        username: 'muhammad.rafi419',
        password: _password,
      ).toRequestBody();

      // Absent, not null: the backend derives the semester on a missing key
      // and answers INVALID_SEMESTER for a present-but-empty one.
      expect(body.containsKey('given_semester'), isFalse);
      expect(body.keys, containsAll(<String>['username', 'password']));
    });

    test('a blank semester is treated as "not supplied"', () {
      for (final blank in ['', '   ', '\n']) {
        final credentials = SlcmCredentials(
          username: 'a.b',
          password: _password,
          givenSemester: blank,
        );
        expect(credentials.givenSemester, isNull, reason: 'blank: "$blank"');
        expect(credentials.toRequestBody().containsKey('given_semester'),
            isFalse);
      }
    });

    test('username is trimmed, because a keyboard space reads as invalid', () {
      final credentials = SlcmCredentials(
        username: '  muhammad.rafi419 ',
        password: _password,
      );
      expect(credentials.username, 'muhammad.rafi419');
      expect(credentials.toRequestBody()['username'], 'muhammad.rafi419');
    });

    test('semester is trimmed but otherwise passed through verbatim', () {
      final credentials = SlcmCredentials(
        username: 'a.b',
        password: _password,
        givenSemester: ' 11 ',
      );
      expect(credentials.givenSemester, '11');
    });
  });

  group('the password must not leak', () {
    test('toString redacts it', () {
      final text = SlcmCredentials(
        username: 'muhammad.rafi419',
        password: _password,
      ).toString();

      expect(text, isNot(contains(_password)));
      expect(text, contains('<redacted>'));
      // The username is not a secret and is useful in a log line.
      expect(text, contains('muhammad.rafi419'));
    });

    test('string interpolation cannot expose it either', () {
      final credentials = SlcmCredentials(
        username: 'a.b',
        password: _password,
      );
      expect('$credentials', isNot(contains(_password)));
    });

    test('toRequestBody is the only member that returns it', () {
      final credentials = SlcmCredentials(
        username: 'a.b',
        password: _password,
      );
      // The field itself is readable - the datasource needs it - but nothing
      // that stringifies or serialises the object may carry it.
      expect(credentials.password, _password);
      expect(credentials.toString(), isNot(contains(_password)));
      expect(credentials.toRequestBody()['password'], _password);
    });
  });

  group('isComplete gates the submit button', () {
    test('false when either field is empty or blank', () {
      expect(
        SlcmCredentials(username: '', password: _password).isComplete,
        isFalse,
      );
      expect(
        SlcmCredentials(username: '   ', password: _password).isComplete,
        isFalse,
      );
      expect(
        SlcmCredentials(username: 'a.b', password: '').isComplete,
        isFalse,
      );
    });

    test('true once both carry something', () {
      expect(
        SlcmCredentials(username: 'a.b', password: _password).isComplete,
        isTrue,
      );
    });
  });
}
